(()=>{'use strict';
const links=[['home','首页','index.html'],['workshop','融卡工坊','workshop.html'],['shop','周边商店','shop.html'],['collection','收藏室','collection.html'],['mailbox','岛主信箱','mailbox.html'],['office','事务所','office.html'],['resident','个人中心','resident.html'],['guide','登岛导览','guide.html']];
const key=document.body.dataset.page||'home';const h=(title,lead)=>'<header class="page-title"><span class="eyebrow">不吱岛 2.0 · 独立页面</span><h1>'+title+'</h1><p>'+lead+'</p></header>';const link=(id,label,style='button')=>'<a class="'+style+'" href="'+links.find(x=>x[0]===id)[2]+'">'+label+'</a>';
function validDouyin(url){try{const u=new URL(url);return u.protocol==='https:'&&['douyin.com','www.douyin.com','v.douyin.com'].includes(u.hostname)?u.href:null}catch{return null}}
const socialLinks=window.BUZHI_SOCIAL_LINKS||{};
function sharedDouyinEntry(){const url=validDouyin(socialLinks.sharedDouyin);return url?'<a class="douyin-link" href="'+url+'" target="_blank" rel="noopener noreferrer" aria-label="访问菜菜与吱吱共同经营的抖音主页（新窗口）"><strong>雾岛吱&菜Gina🐟</strong><span>我们的抖音主页 ↗</span></a>':'<span class="douyin-link is-unset" aria-label="共同抖音主页链接待配置"><strong>雾岛吱&菜Gina🐟</strong><span>抖音主页链接待设置</span></span>'}

const cards=[['SR','海风来信'],['R','贝壳耳语'],['N','小岛邮戳']]; const sample=cards.map((x,i)=>'<button type="button" class="card-select" data-card="'+i+'" aria-pressed="'+(i===0?'true':'false')+'"><span class="status">'+x[0]+' · 演示</span><strong>'+x[1]+'</strong><small>仅占位，不代表账户拥有</small></button>').join('');
const pages={
home:()=>'<section class="island-home" aria-label="吱吱生日主题首页"><div class="island-home-hero"><div class="home-cloud cloud-a" aria-hidden="true"></div><div class="home-cloud cloud-b" aria-hidden="true"></div><div class="home-masthead"><span class="home-birthday-kicker">✦ 不吱岛 · 吱吱的生日季 ✦</span><h1>给你留了一张，<em>靠海的位置。</em></h1><p>致那个初见有点冷、熟了有点疯，唱起歌来却很温柔的吱吱。</p></div><div class="home-island-picture"><div class="home-orbit" aria-hidden="true"></div><img src="../assets/island.svg" alt="不吱岛现有海岛插画；吱吱专属立绘等待正式素材替换" width="720" height="760" loading="eager"><span class="home-picture-caption">海岛插画示意 · 角色素材待替换</span></div><div class="home-postcard"><span class="postcard-stamp">BUZHI · FROM THE SEA</span><strong>致吱吱，也致每位回岛的你。</strong><span>菜菜把这些小事，都写在海风里。</span></div><div class="home-shared-social" aria-label="两位岛主的共同抖音主页"><span>菜菜 × 吱吱 · 一起经营的小窝</span>'+sharedDouyinEntry()+'</div></div><div class="home-book" aria-label="生日内容书桌"><div class="home-book-heading"><span class="eyebrow">THE ISLAND DIARY · 海风手账</span><h2>翻开一封岛主的信</h2><p>有些话不必当面说，海风会替我们送到。</p></div><div class="tabs home-book-tabs" role="tablist" aria-label="生日手账内容"><button type="button" class="button" id="letter-tab" role="tab" aria-controls="letter-panel" aria-selected="true" tabindex="0">✉ 来信</button><button type="button" class="button" id="memory-tab" role="tab" aria-controls="memory-panel" aria-selected="false" tabindex="-1">✧ 回忆</button></div><section class="home-book-page" role="tabpanel" id="letter-panel" aria-labelledby="letter-tab" tabindex="0"><span class="home-paper-mark" aria-hidden="true">BUZHI<br>ISLAND</span><h3>她只是看起来有一点凶。</h3><p>第一次认识吱吱，也许会觉得她说话直接，不太好接近。</p><p>可相处久了就会发现，她总是留意那些不经意的小事。她很爱搞抽象，唱起歌来却能让海风安静。</p><p class="home-book-signature">—— 菜菜视角的文案提案</p></section><section class="home-book-page" role="tabpanel" id="memory-panel" aria-labelledby="memory-tab" tabindex="0" hidden><span class="home-paper-mark" aria-hidden="true">MEMORY<br>BOOK</span><h3>在小岛上，把喜欢留下。</h3><p>唱歌、抽象名场面，还有藏在日常里的细心瞬间。</p><p>回忆素材尚待岛主确认；这里不展示虚构的卡牌收藏或中奖结果。</p></section></div></section>',
workshop:()=>"<div class=\"craft-world\"><header class=\"craft-stage-head\"><span class=\"eyebrow\">BUZHI ISLAND · CARD ATELIER</span><h1>潮汐融卡工坊</h1><p>把重复的回忆放上潮汐工作台。合成规则尚待确认，所有卡牌都是演示，不会扣除真实收藏。</p></header><div class=\"craft-layout\"><section class=\"craft-table\" aria-label=\"融卡操作台\"><div class=\"craft-desk\"><span class=\"eyebrow\">第一步 · 选择素材</span><h2>摆上想要融入的卡片</h2><p>点击下方演示卡片，可以切换选中状态；正式版会读取你实际拥有的重复卡数量。</p><div class=\"craft-slots\" aria-label=\"卡牌融合预览\"><div class=\"craft-slot\" id=\"fusion-input-slot\">待选择素材卡</div><div class=\"craft-sigil\" aria-hidden=\"true\">✧</div><div class=\"craft-slot craft-result\" id=\"fusion-output-slot\">融合产物待规则确认</div></div><div class=\"craft-cards\" id=\"fusion-cards\"><button class=\"craft-card\" type=\"button\" data-fusion-choice=\"0\" aria-pressed=\"false\"><small>SR · 演示</small><strong>海风来信</strong><span>不代表账户拥有</span></button><button class=\"craft-card\" type=\"button\" data-fusion-choice=\"1\" aria-pressed=\"false\"><small>R · 演示</small><strong>贝壳耳语</strong><span>不代表账户拥有</span></button><button class=\"craft-card\" type=\"button\" data-fusion-choice=\"2\" aria-pressed=\"false\"><small>N · 演示</small><strong>小岛邮戳</strong><span>不代表账户拥有</span></button></div><p id=\"fusion-feedback\" class=\"muted\" role=\"status\">还没有选择演示卡牌。</p></div></section><aside class=\"craft-aside\"><section class=\"craft-rule-scroll\"><span class=\"eyebrow\">第二步 · 查阅规则</span><h2>吱吱的工作台说明</h2><p>别急着丢进去，先看清楚要用什么。</p><dl><dt>消耗卡牌数量</dt><dd>待确认</dd><dt>是否需要同名卡</dt><dd>待确认</dd><dt>消耗金币</dt><dd>待确认</dd><dt>合成结果与概率</dt><dd>待确认</dd></dl></section><section class=\"craft-confirm\"><span class=\"eyebrow\">第三步 · 核对后确认</span><h2>潮汐还没有开始</h2><p>未公布的规则不能提前扣卡。正式版需二次确认、重复提交保护和交易流水。</p><button class=\"button primary\" disabled type=\"button\">合成暂未开放</button><p class=\"muted\">演示只切换卡面，不触发任何交易。</p></section></aside></div></div>",
shop:()=>"<div class=\"merch-world\"><header class=\"merch-arch\"><span class=\"eyebrow\">BUZHI ISLAND · SEASIDE EXCHANGE</span><h1>不吱岛周边兑换店</h1><p>海风把纪念品送到橱窗里，想兑换之前，先看看资格、数量和记录。</p></header><div class=\"merch-layout\"><section class=\"merch-showcase\"><div class=\"merch-shelf-top\"><h2>沿海橱窗</h2><p class=\"muted\">当前只展示商品位示意，未配置正式商品或库存。</p></div><div class=\"merch-shelf\"><button type=\"button\" class=\"merch-item\" data-merch-choice=\"0\" aria-pressed=\"false\"><span class=\"merch-display\">纪念卡<br>图像位置</span><strong>周边卡片展示位</strong><small>待配置商品资料</small></button><button type=\"button\" class=\"merch-item\" data-merch-choice=\"1\" aria-pressed=\"false\"><span class=\"merch-display\">海岛信物<br>图像位置</span><strong>小岛信物展示位</strong><small>待配置商品资料</small></button></div><p id=\"merch-feedback\" role=\"status\" class=\"muted\">点选一个橱窗商品位，查看兑换状态。</p></section><aside class=\"merch-counter\"><span class=\"eyebrow\">岛主兑换柜台</span><h2>先核对，再兑换</h2><div class=\"merch-receipt\"><div><span>选择商品</span><strong id=\"merch-selected\">尚未选择</strong></div><div><span>库存</span><strong>未接入</strong></div><div><span>兑换消耗</span><strong>待确认</strong></div><div><span>资格状态</span><strong>未验证</strong></div></div><p>正式版会先校验身份和商品库存，再展示可确认的消耗清单。失败或超时后先查询兑换记录，不自动重试扣款。</p><button class=\"button primary\" type=\"button\" disabled>尚未开放兑换</button><section class=\"merch-records\"><h3>兑换小票与历史</h3><p class=\"muted\">未来只展示服务器保存的订单与结果。当前不会生成假订单。</p></section></aside></div></div>",
collection:()=>h('回忆收藏室','画廊骨架。保留往期卡牌与收藏功能的独立入口，未来由真实会话读取用户收藏。')+'<section class="surface"><div class="actions"><label class="field">筛选稀有度<select id="rarity"><option value="all">全部</option><option value="SR">SR</option><option value="R">R</option><option value="N">N</option></select></label></div><div id="collection-grid" class="card-list section"></div><p class="muted">所有卡片均为静态演示，无真实库存或获得日期。</p></section>',
mailbox:()=>h('岛主信箱','独立来信空间。匿名、实名、后台回复及持久化由后续正式接口负责，预览不会保存或发送任何信息。')+'<div class="layout"><section class="surface"><h2>写给岛主的一封信</h2><div class="fields"><label class="field">署名方式<select id="sender"><option>岛民署名（演示）</option><option>匿名（演示）</option></select></label><label class="field">来信内容<input id="message" type="text" maxlength="200" placeholder="这里只练习输入，不会发送"></label><button class="button" type="button" id="preview-letter">预览信件</button></div><p class="muted" id="letter-feedback" role="status">演示环境：不发送、不存储。</p></section><aside class="surface"><h2>岛主回复展板</h2><div class="placeholder">真实回复、可见范围与审核规则待接入</div></aside></div>',
office:()=>"<div class=\"office-world\" aria-label=\"吱吱值班的岛民事务所\">\n<section class=\"office-counter\"><div class=\"office-copy\"><span class=\"eyebrow\">BUZHI ISLAND · 今日值班</span><h1>岛民事务所</h1><p class=\"office-quote\">吱吱：有事直说，别漏了。办好了我给你记上。</p><p class=\"muted\">吱吱值班，菜菜协助。任务与金币奖励只由正式服务端决定。</p></div><div class=\"office-scene\" aria-label=\"吱吱办公桌场景素材位\"><span>吱吱值班立绘</span><span>桌上的屁宝与蓝鸟花 · 待视觉设计替换</span></div></section>\n<div class=\"office-stations\">\n<section class=\"office-board office-station\" aria-labelledby=\"office-board-title\"><span class=\"office-stamp\">01 / 委托公告板</span><h2 id=\"office-board-title\">先看看今天要办什么</h2><p>生日来信、岛屿回忆、默契小测与其他原有任务，未来按正式活动状态展示。</p><div class=\"office-paper\"><strong>今日事务 · 数据尚未接入</strong><p>目前没有读取真实账户任务，请不要把演示内容当作已领取或已完成。</p><span class=\"status\">未连接活动 API</span></div></section>\n<section class=\"office-files office-station\" aria-labelledby=\"office-files-title\"><span class=\"office-stamp\">02 / 办结档案</span><h2 id=\"office-files-title\">完成过的，都记着呢</h2><p>这里预留原有任务进度、签到和奖励记录的只读视图。</p><div class=\"office-drawer\" role=\"note\">岛民档案待登录后读取 · 不重建历史记录</div></section>\n<section class=\"office-music office-station\" aria-labelledby=\"office-music-title\"><span class=\"office-stamp\">03 / 海风点歌簿</span><h2 id=\"office-music-title\">有首歌想让吱吱听见？</h2><p>写下一首歌或一段音乐回忆。这是页面内的练习纸条，不会发送给岛主，也不构成点歌承诺。</p><form id=\"office-song-form\" class=\"office-note-form\"><label for=\"office-song\">歌曲或音乐心愿</label><input id=\"office-song\" maxlength=\"80\" placeholder=\"一首想分享的歌\"><button class=\"button\" type=\"submit\">在纸上试写</button><p id=\"office-song-feedback\" class=\"muted\" role=\"status\">仅本页演示 · 不保存 · 不发金币</p></form></section>\n<section class=\"office-bird office-station\" aria-labelledby=\"office-bird-title\"><span class=\"office-stamp\">04 / 肥啾临时委托</span><h2 id=\"office-bird-title\">办公室出现离谱事件</h2><p>肥啾说蛋糕自己走进了它嘴里。你觉得吱吱会怎么说？</p><fieldset class=\"office-choices\"><legend>选择一个回答</legend><label><input type=\"radio\" name=\"bird-excuse\" value=\"report\">「你先把检查报告交上来。」</label><label><input type=\"radio\" name=\"bird-excuse\" value=\"cake\">「行，让蛋糕自己来解释。」</label><label><input type=\"radio\" name=\"bird-excuse\" value=\"feather\">「三根羽毛赔偿？你还剩几根？」</label></fieldset><p id=\"office-bird-response\" class=\"office-reaction\" role=\"status\">吱吱：先别急着选，查明白再说。</p><small>纯趣味彩蛋，不对应正式任务或金币奖励。</small></section></div>\n<p class=\"office-footer-note\">吱吱说话直接，但重要的记录会认真替你留着。正式任务、奖励、历史与认证须在真实账号服务完成接入后才能操作。</p>\n</div>",
resident:()=>h('岛民个人中心','账户信息、认证、卡牌、金币记录的容器骨架。预览不要求登录，不会读取正式用户资料。')+'<section class="surface" id="account-access" tabindex="-1"><h2>登录与退出登录</h2><p>当前为静态工程预览，尚未连接正式认证服务。此处不接收密码，也不会模拟登录成功。正式版将沿用原有岛民登录与账户找回流程；登录后顶部显示退出登录。</p><span class="status">当前：访客模式</span></section><section class="surface section" aria-labelledby="account-settings-title"><h2 id="account-settings-title">岛民账户设置</h2><p class="muted">已有岛民可沿用 BZI 编号。下列编辑项在接入原有会话前仅展示位置，不接受真实资料。</p><div class="account-settings-grid"><div class="account-setting"><strong>岛民显示昵称</strong><p>可在正式接入后修改，不会变更岛民编号或已有收藏。</p><label for="resident-nickname-preview">新的显示昵称</label><input id="resident-nickname-preview" disabled placeholder="连接账户后可编辑"><button type="button" class="button" disabled>保存昵称 · 待接入</button></div><div class="account-setting"><strong>账号与安全</strong><p>原 BZI 编号永久保留；密码修改沿用已有服务端接口。</p><button type="button" class="button" disabled>修改密码 · 待接入</button><button type="button" class="button" disabled>退出当前账号 · 待接入</button></div></div></section><div class="layout section"><section class="surface"><h2>岛民档案</h2><div class="placeholder">OC 肖像与岛民身份信息素材位</div><p>身份、认证与居住岛屿信息都需要真实登录会话。</p></section><aside class="surface"><h2>我的记录</h2><div class="list"><article>金币账本 · 只读接入点</article><article>收藏记录 · 只读接入点</article><article>兑换记录 · 只读接入点</article></div></aside></div>',
guide:()=>h('登岛导览','新岛民的独立上手页面；引导页面而非真实注册或认证流程。')+'<section class="surface"><h2>登岛路径</h2><div class="tiles">'+[['resident','先认识自己的岛民档案'],['office','再看岛上事务'],['collection','最后收藏小岛回忆']].map((x,i)=>'<a class="tile" href="'+links.find(v=>v[0]===x[0])[2]+'"><strong>第 '+(i+1)+' 站</strong><p>'+x[1]+'</p></a>').join('')+'</div></section>'
};
const authControls='<a class="button auth-login" href="resident.html#account-access">登录</a><button type="button" class="button auth-logout" disabled title="当前静态预览未登录，正式退出功能待接入账户接口">退出登录</button>';
const nav=(a)=>'<a href="'+a[2]+'" '+(a[0]===key?'aria-current="page"':'')+'>'+a[1]+'</a>';document.querySelector('#app').innerHTML='<div class="site"><header class="masthead"><a class="brand" href="index.html">不吱岛<small>BUZHI ISLAND · 2.0</small></a><nav class="nav" aria-label="站点导航">'+links.map(nav).join('')+'</nav><div class="controls"><span class="auth-status" role="status">访客模式</span>'+authControls+'<button id="motion" class="button" type="button" aria-pressed="false">减少动效</button></div></header><div class="banner" role="status">工程结构预览 · 未接入正式账户、卡池、金币或兑换服务 · 所有操作均为本地演示</div><details class="mobile-more"><summary>全部页面导航 · 当前：' + links.find(x=>x[0]===key)[1] + '</summary><nav class="mobile-more-links" aria-label="全部页面导航">' + links.map(nav).join('') + '</nav></details><main id="content">'+pages[key]()+'</main><footer class="site-footer">不吱岛 · 双岛主：菜菜与吱吱　｜　2.0 多页面工程骨架 · 不可作为正式交易入口</footer></div><nav class="mobile-nav" aria-label="手机导航">'+['home','office','workshop','collection','resident'].map(k=>nav(links.find(x=>x[0]===k))).join('')+'</nav>';
const tabs=[...document.querySelectorAll('[role="tab"][aria-controls]')];function setBirthdayTab(id,focus=false){const target=tabs.find(t=>t.getAttribute('aria-controls')===id);if(!target)return;tabs.forEach(t=>{const active=t===target;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;const panel=document.getElementById(t.getAttribute('aria-controls'));if(panel)panel.hidden=!active});if(focus)target.focus()}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>setBirthdayTab(tab.getAttribute('aria-controls')));tab.addEventListener('keydown',e=>{let idx;if(e.key==='ArrowRight')idx=(i+1)%tabs.length;else if(e.key==='ArrowLeft')idx=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')idx=0;else if(e.key==='End')idx=tabs.length-1;else return;e.preventDefault();setBirthdayTab(tabs[idx].getAttribute('aria-controls'),true)})});if(tabs.length&&location.hash)setBirthdayTab(location.hash.slice(1));
const motion=document.querySelector('#motion');motion.addEventListener('click',()=>{const yes=document.body.classList.toggle('reduce-motion');motion.setAttribute('aria-pressed',String(yes));motion.textContent=yes?'恢复动效':'减少动效'});
document.querySelectorAll('[data-card]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-card]').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));document.querySelector('#selection-summary').textContent='已选演示卡牌：'+btn.querySelector('strong').textContent}));
const rarity=document.querySelector('#rarity');const render=()=>{if(!rarity)return;const v=rarity.value;document.querySelector('#collection-grid').innerHTML=cards.filter(x=>v==='all'||x[0]===v).map(x=>'<article class="tile"><span class="status">'+x[0]+'</span><strong>'+x[1]+'</strong><p>演示卡面占位</p></article>').join('')};if(rarity){rarity.addEventListener('change',render);render()}
document.querySelectorAll('[data-fusion-choice]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-fusion-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));const label=btn.querySelector('strong').textContent;document.querySelector('#fusion-input-slot').textContent=label+' · 演示素材';document.querySelector('#fusion-feedback').textContent='已选择演示卡片：'+label+'。真实持有数量与融合规则尚未读取。'}));
document.querySelectorAll('[data-merch-choice]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-merch-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));const label=btn.querySelector('strong').textContent;document.querySelector('#merch-selected').textContent=label;document.querySelector('#merch-feedback').textContent='已选中展示位：'+label+'。库存与兑换规则未配置，无法兑换。'}));
const sf=document.querySelector('#shop-filter');if(sf)sf.addEventListener('change',()=>{document.querySelector('#shop-message').textContent='筛选演示：'+sf.options[sf.selectedIndex].text+'。商品信息未绑定库存。'});
const songForm=document.querySelector('#office-song-form');if(songForm)songForm.addEventListener('submit',e=>{e.preventDefault();const v=document.querySelector('#office-song').value.trim();document.querySelector('#office-song-feedback').textContent=v?'已经在这张演示纸条上写下《'+v+'》。刷新后不会保留，也没有发送给岛主。':'先写下歌名或音乐心愿哦。'});
document.querySelectorAll('input[name="bird-excuse"]').forEach(r=>r.addEventListener('change',()=>{const lines={report:'吱吱：检查完了？报告拿来我看看。',cake:'吱吱：行，那你把蛋糕叫过来。',feather:'吱吱：你先数数自己还剩几根毛。'};document.querySelector('#office-bird-response').textContent=lines[r.value]}));
const letter=document.querySelector('#preview-letter');if(letter)letter.addEventListener('click',()=>{const str=document.querySelector('#message').value.trim();document.querySelector('#letter-feedback').textContent=str?'预览字数：'+Array.from(str).length+' 字；没有发送也没有保存。':'请先输入内容以查看演示字数。'});
})();